fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n >= 4 {
                // If n >= 4, we only need to add 1 when n is odd, 0 when even.
                n % 2
            } else {
                // For n == 2 or 3, we need to reach at least 4.
                4 - n
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_various() {
        // n < 4
        assert_eq!(solve(vec![2]), vec![2]); // 2 -> needs +2 to reach 4
        assert_eq!(solve(vec![3]), vec![1]); // 3 -> needs +1 to reach 4

        // n >= 4 and even
        assert_eq!(solve(vec![4, 6, 10]), vec![0, 0, 0]);

        // n >= 4 and odd
        assert_eq!(solve(vec![5, 7, 11]), vec![1, 1, 1]);

        // mixed
        let input = vec![2, 3, 4, 5, 8, 9];
        let expected = vec![2, 1, 0, 1, 0, 1];
        assert_eq!(solve(input), expected);
    }
}